def normalize_words(value):
    return " ".join(value.casefold().split())

def compact_words(value):
    return "".join(ch for ch in value.casefold() if ch.isalnum())

def target_line_indexes(content):
    target_key = normalize_words(target_item)
    return [
        index for index, line in enumerate(content.splitlines(keepends=True))
        if target_key in normalize_words(line)
    ]

item_notes = [detail for detail in note_details if target_line_indexes(detail["content"])]
if not item_notes:
    raise RuntimeError("No searched note contains the requested Bucket List item")
search_position = {note_id: index for index, note_id in enumerate(note_candidate_order)}

def note_rank(detail):
    title_key = compact_words(detail["title"])
    if title_key == "bucketlist":
        title_rank = 0
    elif "bucketlist" in title_key:
        title_rank = 1
    else:
        title_rank = 2
    return (title_rank, search_position[detail["note_id"]])

selected_note = min(item_notes, key=note_rank)
selected_note_id = selected_note["note_id"]
original_content = selected_note["content"]

def checkbox_span_and_state(line):
    start = 0
    while True:
        left = line.find("[", start)
        if left < 0:
            return None, None
        right = line.find("]", left + 1)
        if right < 0:
            return None, None
        inside = line[left + 1:right].strip().casefold()
        if inside == "":
            return (left, right), "unchecked"
        if inside == "x":
            return (left, right), "checked"
        start = right + 1

def line_is_done(line):
    span, state = checkbox_span_and_state(line)
    if state == "checked":
        return True
    if any(marker in line for marker in ("☑", "✅", "✔")):
        return True
    exact_index = line.casefold().find(target_item.casefold())
    if exact_index >= 2:
        exact_end = exact_index + len(target_item)
        if line[exact_index - 2:exact_index] == "~~" and line[exact_end:exact_end + 2] == "~~":
            return True
    return False

def mark_line_done(line):
    span, state = checkbox_span_and_state(line)
    if state == "checked":
        return line
    if state == "unchecked":
        left, right = span
        return line[:left] + "[x]" + line[right + 1:]
    for old_marker, new_marker in (("☐", "☑"), ("⬜", "✅"), ("❌", "✅")):
        if old_marker in line:
            return line.replace(old_marker, new_marker, 1)
    if line_is_done(line):
        return line
    indentation_length = len(line) - len(line.lstrip(" \t"))
    indentation = line[:indentation_length]
    body = line[indentation_length:]
    for bullet in ("- ", "* ", "+ "):
        if body.startswith(bullet):
            return indentation + bullet + "[x] " + body[len(bullet):]
    dot_space = body.find(". ")
    if dot_space > 0 and body[:dot_space].isdigit():
        insertion = dot_space + 2
        return indentation + body[:insertion] + "[x] " + body[insertion:]
    return indentation + "[x] " + body

content_lines = original_content.splitlines(keepends=True)
matched_line_indexes = target_line_indexes(original_content)
line_changes = []
for line_index in matched_line_indexes:
    before_line = content_lines[line_index]
    after_line = mark_line_done(before_line)
    content_lines[line_index] = after_line
    line_changes.append({"before": before_line, "after": after_line})
updated_content = "".join(content_lines)
needs_update = updated_content != original_content
print({
    "selected_note": {"note_id": selected_note_id, "title": selected_note["title"]},
    "matching_item_lines": len(matched_line_indexes),
    "line_changes": line_changes,
    "needs_update": needs_update,
})

